import Model from 'flarum/common/Model';
export default class RewindSnapshot extends Model {
  year = (() => Model.attribute('year'))();
  snapshotData = (() => Model.attribute('data'))();
  generatedAt = (() => Model.attribute('generatedAt', Model.transformDate))();
  isPublic = (() => Model.attribute('isPublic'))();
  canEdit = (() => Model.attribute('canEdit'))();
  canModerate = (() => Model.attribute('canModerate'))();
  isEmpty = (() => Model.attribute('isEmpty'))();
  user = (() => Model.hasOne('user'))();
}
flarum.reg.add('huseyinfiliz-rewind', 'common/models/RewindSnapshot', RewindSnapshot);